		if(bId.equals("Dtl_Sls_Schd")) return getDtl_Sls_SchdL();
		if(bId.equals("Dtl_Ship_Act")) return getDtl_Ship_ActL();
		if(bId.equals("Dtl_Slo_Prms_his")) return getDtl_Slo_Prms_hisL();
		if(bId.equals("Btn")) return getBtnR();
		if(bId.equals("Dtl_Ship_Schd_All")) return getDtl_Ship_Schd_AllL();
		if(bId.equals("Dtl_Slo_Prms_All")) return getDtl_Slo_Prms_AllL();
		if(bId.equals("Dtl_Slo_Sts_All")) return getDtl_Slo_Sts_AllL();
		if(bId.equals("Dtl_Alloc_Sts_All")) return getDtl_Alloc_Sts_AllL();
