	/**
	 * リストを保持する画面部品のリストを返します。
	 */
	public MCList getList(MCEventBeans combo, MCRow row, MCEventInfo info) {
		MCList list = super.getList(combo, row, info);
		if(list != null) return list;
		if(combo == Hdr_can_rsn_cd) return getHdr_can_rsn_cd(row, info);
		if(combo == columnDtl_gd_cd) return getDtl_gd_cd(row, info);
		if(combo == columnDtl_can_rsn_cd) return getDtl_can_rsn_cd(row, info);
		if(combo == columnDtl_Ship_Schd_ship_fr_lg_grp_cd) return getDtl_Ship_Schd_ship_fr_lg_grp_cd(row, info);
		if(combo == columnDtl_Ship_Schd_wg_cd) return getDtl_Ship_Schd_wg_cd(row, info);
		if(combo == columnDtl_Ship_Schd_ship_term_cd) return getDtl_Ship_Schd_ship_term_cd(row, info);
		if(combo == columnDtl_Ship_Schd_ship_wk_cd) return getDtl_Ship_Schd_ship_wk_cd(row, info);
		if(combo == Dtl_Ship_Schd_dlv_p_PPanel.columnDlv_bp_cd) return getDtl_Ship_Schd_dlv_p_PPanel_columnDlv_bp_cd(row, info);
		if(combo == Dtl_Ship_Schd_tdlv_p_PPanel.columnDlv_bp_cd) return getDtl_Ship_Schd_tdlv_p_PPanel_columnDlv_bp_cd(row, info);
		if(combo == columnDtl_Ship_Schd_via_dlv_typ) return getDtl_Ship_Schd_via_dlv_typ(row, info);
		if(combo == columnDtl_Ship_Schd_dlv_day_week_typ_nm) return getDtl_Ship_Schd_dlv_day_week_typ_nm(row, info);
		return null;
	}

	/**
	 * ActionPerformedイベントが実行されたときに呼び出されます。
	 *
	 * @param ap ActionPerformedイベントが実行されたGUI部品
	 */
	public void doAPEvent(MCAPBeans ap, MCEventInfo info) {
		super.doAPEvent(ap, info);
		if (ap == Cnd_srch) doCnd_srch(info);
		else if (ap == CtLeftBtn_radd) doCtLeftBtn_radd(info);
		else if (ap == CtLeftBtn_rdel) doCtLeftBtn_rdel(info);
		else if (ap == CtLeftBtn_rcopy) doCtLeftBtn_rcopy(info);
		else if (ap == CtRightBtn_dlvSchdUpd) doCtRightBtn_dlvSchdUpd(info);
		else if (ap == CtRightBtn_radd) doCtRightBtn_radd(info);
		else if (ap == CtRightBtn_rdel) doCtRightBtn_rdel(info);
		else if (ap == CtRightBtn_rcopy) doCtRightBtn_rcopy(info);
		else if (ap == Btn_open_MSBBP1210) doBtn_open_MSBBP1210(info);
		else if (ap == Btn_open_MSBBP1240) doBtn_open_MSBBP1240(info);
		else if (ap == Btn_open_MSBEP0060) doBtn_open_MSBEP0060(info);
		else if (ap == Btn_open_MSBEP0040) doBtn_open_MSBEP0040(info);
		else if (ap == Btn_open_MSBCP0080) doBtn_open_MSBCP0080(info);
		else if (ap == Btn_prnt_prms) doBtn_prnt_prms(info);
		else if (ap == Btn_upd) doBtn_upd(info);
	}

